class ServiceProxy(private val real: ServiceApi) : ServiceApi by real {

    override fun call(request: Request): Response {     // only what needs control
        val started = System.nanoTime()
        return try {
            real.call(request)                          // same contract
        } finally {
            metrics.record("call", System.nanoTime() - started)
        }
    }
}

