class PolicyInterceptor : ServerInterceptor {
    override fun <ReqT, RespT> interceptCall(
        call: ServerCall<ReqT, RespT>,
        headers: Metadata,
        next: ServerCallHandler<ReqT, RespT>,
    ): ServerCall.Listener<ReqT> {
        val started = System.nanoTime()                       // policy
        return next.startCall(RecordingCall(call, started), headers)
    }
}
